package com.bank.settle.service;

import java.util.logging.Logger;

// Searches a sorted array rotated at an unknown pivot (distinct values).
public class SettlementSearchService {
    private static final Logger log = Logger.getLogger(SettlementSearchService.class.getName());

    public int indexOf(int[] seq, int key) {
        int start = 0, end = seq.length - 1;
        while (start <= end) {
            int mid = start + (end - start) / 2;
            if (seq[mid] == key) {
                final int found = mid;
                log.info(() -> "Key " + key + " found at index " + found);
                return mid;
            }
            if (seq[start] <= seq[mid]) {               // left half is sorted
                if (key >= seq[start] && key < seq[mid]) end = mid - 1;
                else start = mid + 1;
            } else {                                     // right half is sorted
                if (key > seq[mid] && key <= seq[end]) start = mid + 1;
                else end = mid - 1;
            }
        }
        log.warning(() -> "Key " + key + " not found");
        return -1;
    }
}
